; ============================================================================
; Pokonyan! - Yume no Daibouken (J) - sound driver (Agenda) and sound data
; ROM bank 7, $4000-$7C2F. Generated by tools/agenda_gen.py; reassembles
; byte-identical with RGBDS 1.0.0. See Agenda_SoundDriver.md for the format.
; ============================================================================

INCLUDE "agenda_sound.inc"

; ---- HRAM ----
DEF hSndChannel      EQU $FFB0 ; hardware channel being processed (0-3)
DEF hSndStructOfs    EQU $FFB1 ; struct offset ($00/$30/$60/$90, $C0 = SFX)
DEF hSndTempo        EQU $FFB2 ; frames per tick - 1
DEF hSndTempoCount   EQU $FFB3 ; frame counter for the tempo
DEF hSndFlags        EQU $FFB4 ; bits 0-3 channel on, bit 4 SFX, bit 7 no-loop
DEF hSndMarker       EQU $FFB5 ; last $B4 argument (read by the game)
DEF hSndSlur         EQU $FFB6 ; 1 = $A4 seen in this row
DEF hSndMasterVol    EQU $FFB7 ; NR50 copy ($B6)
DEF hSndSfxChannel   EQU $FFB8 ; channel of the playing SFX
DEF hSndMuted        EQU $FFB9 ; 1 = channel in use by the SFX: no register writes
DEF hSndRetrigger    EQU $FFBA ; 1 = write NRx4 with trigger at the end of the tick
DEF hSndSfxId        EQU $FFBB ; last SFX id
DEF hSndSfxPriority  EQU $FFBC ; priority of the playing SFX
DEF hSndMusicId      EQU $FFBD ; last music id
DEF hSndUnused       EQU $FFBE ; not used by the driver
DEF hSndSfxFrame     EQU $FFBF ; SFX frame divider

; ---- WRAM ----
DEF wSndTracks      EQU $DD00 ; 5 track structs of TRK_SIZEOF: ch1-ch4, SFX
DEF wSndSave        EQU $DE00 ; copy of wSndTracks (Sound_SaveMusic)
DEF wSndSaveHram    EQU $DEF0 ; copy of the 16 HRAM bytes

SECTION "Sound driver", ROMX[$4000], BANK[7]

    db $07, $07                     ; bank number (every bank of this ROM starts with it twice)

; Jump table, called from bank 0.
Sound_JumpTable::
    jp Sound_Update                 ; $4002
    jp Sound_StopMusic              ; $4005
    jp Sound_PlaySfx                ; $4008
    jp Sound_Init                   ; $400B
    jp Sound_PlayMusic              ; $400E
    jp Sound_SaveMusic              ; $4011
    jp Sound_RestoreMusic           ; $4014
    db $00                          ; unused

    ds $68, $FF                     ; unused

; Sound_SaveMusic: back up all track structs and the HRAM variables, then
; start the silent song (all channels free). Used around jingles.
Sound_SaveMusic::
    ldh a,[rIE]                     ; $4080 IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $4082
    res 1,a                         ; $4083
    ldh [rIE],a                     ; $4085
    ld hl,wSndTracks                ; $4087
    ld de,wSndSave                  ; $408A
    ld bc,$0100                     ; $408D
    call Snd_CopyBytes              ; $4090
    ld hl,hSndChannel               ; $4093
    ld de,wSndSaveHram              ; $4096
    ld bc,$0010                     ; $4099
    call Snd_CopyBytes              ; $409C
    ldh a,[hSndFlags]               ; $409F
    and $F0                         ; $40A1
    ldh [hSndFlags],a               ; $40A3
    pop af                          ; $40A5
    ldh [rIE],a                     ; $40A6 restore IE
    call Sound_StopMusic            ; $40A8
    ret                             ; $40AB

; Sound_RestoreMusic: undo Sound_SaveMusic. The wave RAM and the hardware
; registers are not restored; each channel sounds again at its next note.
Sound_RestoreMusic::
    ldh a,[rIE]                     ; $40AC IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $40AE
    res 1,a                         ; $40AF
    ldh [rIE],a                     ; $40B1
    ld hl,wSndSave                  ; $40B3
    ld de,wSndTracks                ; $40B6
    ld bc,$0100                     ; $40B9
    call Snd_CopyBytes              ; $40BC
    ld hl,wSndSaveHram              ; $40BF
    ld de,hSndChannel               ; $40C2
    ld bc,$0010                     ; $40C5
    call Snd_CopyBytes              ; $40C8
    pop af                          ; $40CB
    ldh [rIE],a                     ; $40CC restore IE
    ret                             ; $40CE
Snd_CopyBytes:
    ld a,[hl+]                      ; $40CF
    ld [de],a                       ; $40D0
    inc de                          ; $40D1
    dec bc                          ; $40D2
    ld a,b                          ; $40D3
    or c                            ; $40D4
    jr nz,Snd_CopyBytes             ; $40D5
    ret                             ; $40D7

; Sound_PlaySfx: a = SFX id. Header = [channel 0-3, priority], then track data.
; Ignored if priority < the priority of the SFX already playing.
Sound_PlaySfx::
    ldh [hSndSfxId],a               ; $40D8
    ld l,a                          ; $40DA
    ld h,$00                        ; $40DB
    add hl,hl                       ; $40DD
    ld de,SfxTable                  ; $40DE
    add hl,de                       ; $40E1
    jp Snd_StartSfx                 ; $40E2

; Sound_PlayMusic: a = song id. MusicTable has 4 track pointers per song.
Sound_PlayMusic::
    ldh [hSndMusicId],a             ; $40E5
    ld l,a                          ; $40E7
    ld h,$00                        ; $40E8
    add hl,hl                       ; $40EA
    add hl,hl                       ; $40EB
    add hl,hl                       ; $40EC
    ld de,MusicTable                ; $40ED
    add hl,de                       ; $40F0
    jp Snd_StartMusic               ; $40F1

; Register values written by Sound_Init to NR10-NR23 ($FF10-$FF23)
InitRegs:
    db $08, $00, $02, $00, $80
    db $00, $00, $02, $00, $80
    db $00, $00, $00, $00, $80
    db $00, $00, $02, $00, $80

; Sound_StopMusic: the silent song (4 x the same track)
SilentSong:
    dw SilentTrack, SilentTrack, SilentTrack, SilentTrack
SilentTrack:
    db $B6, $77                     ; master volume (NR50 $77)
    db $A6, $00                     ; volume 0
    db $7F                          ; rest
    db $A0                          ; end (loop to start; stop if $A2)

; $A6 on ch3: volume 0-15 -> NR32 output level
WaveVolTable:
    db $00, $00, $60, $60, $60, $60, $40, $40, $40, $40, $20, $20, $20, $20, $20, $20

; Length codes $80-$92 (ticks)
LengthTable:
    db 128                          ; $80
    db 96                           ; $81
    db 64                           ; $82
    db 48                           ; $83
    db 32                           ; $84
    db 24                           ; $85
    db 16                           ; $86
    db 12                           ; $87
    db 8                            ; $88
    db 6                            ; $89
    db 4                            ; $8A
    db 3                            ; $8B
    db 2                            ; $8C
    db 1                            ; $8D
    db 144                          ; $8E
    db 72                           ; $8F
    db 36                           ; $90
    db 18                           ; $91
    db 9                            ; $92

; Periods for notes $24 (C2) and up
FreqTable:
    dw $002C                        ; note $24 C2
    dw $009D                        ; note $25 C#2
    dw $0107                        ; note $26 D2
    dw $016B                        ; note $27 D#2
    dw $01C9                        ; note $28 E2
    dw $0223                        ; note $29 F2
    dw $0277                        ; note $2A F#2
    dw $02C7                        ; note $2B G2
    dw $0312                        ; note $2C G#2
    dw $0358                        ; note $2D A2
    dw $039B                        ; note $2E A#2
    dw $03DA                        ; note $2F B2
    dw $0416                        ; note $30 C3
    dw $044E                        ; note $31 C#3
    dw $0483                        ; note $32 D3
    dw $04B5                        ; note $33 D#3
    dw $04E5                        ; note $34 E3
    dw $0511                        ; note $35 F3
    dw $053B                        ; note $36 F#3
    dw $0563                        ; note $37 G3
    dw $0589                        ; note $38 G#3
    dw $05AC                        ; note $39 A3
    dw $05CD                        ; note $3A A#3
    dw $05ED                        ; note $3B B3
    dw $060C                        ; note $3C C4
    dw $0627                        ; note $3D C#4
    dw $0642                        ; note $3E D4
    dw $065B                        ; note $3F D#4
    dw $0672                        ; note $40 E4
    dw $0689                        ; note $41 F4
    dw $069E                        ; note $42 F#4
    dw $06B2                        ; note $43 G4
    dw $06C4                        ; note $44 G#4
    dw $06D6                        ; note $45 A4
    dw $06E7                        ; note $46 A#4
    dw $06F7                        ; note $47 B4
    dw $0706                        ; note $48 C5
    dw $0714                        ; note $49 C#5
    dw $0721                        ; note $4A D5
    dw $072D                        ; note $4B D#5
    dw $0739                        ; note $4C E5
    dw $0744                        ; note $4D F5
    dw $074F                        ; note $4E F#5
    dw $0759                        ; note $4F G5
    dw $0762                        ; note $50 G#5
    dw $076B                        ; note $51 A5
    dw $0773                        ; note $52 A#5
    dw $077B                        ; note $53 B5
    dw $0783                        ; note $54 C6
    dw $078A                        ; note $55 C#6
    dw $0790                        ; note $56 D6
    dw $0797                        ; note $57 D#6
    dw $079D                        ; note $58 E6
    dw $07A2                        ; note $59 F6
    dw $07A7                        ; note $5A F#6
    dw $07AC                        ; note $5B G6
    dw $07B1                        ; note $5C G#6
    dw $07B6                        ; note $5D A6
    dw $07BA                        ; note $5E A#6
    dw $07BE                        ; note $5F B6
    dw $07C1                        ; note $60 C7
    dw $07C5                        ; note $61 C#7
    dw $07C8                        ; note $62 D7
    dw $07CB                        ; note $63 D#7
    dw $07CE                        ; note $64 E7
    dw $07D1                        ; note $65 F7
    dw $07D4                        ; note $66 F#7
    dw $07D6                        ; note $67 G7
    dw $07D9                        ; note $68 G#7
    dw $07DB                        ; note $69 A7
    dw $07DD                        ; note $6A A#7
    dw $07DF                        ; note $6B B7
    dw $07E1                        ; note $6C C8
    dw $07E2                        ; note $6D C#8
    dw $07E4                        ; note $6E D8
    dw $07E6                        ; note $6F D#8
    dw $07E7                        ; note $70 E8
    dw $07E9                        ; note $71 F8
    dw $07EA                        ; note $72 F#8
    dw $07EB                        ; note $73 G8
    dw $07EC                        ; note $74 G#8
    dw $07ED                        ; note $75 A8
    dw $07EE                        ; note $76 A#8
    dw $07EF                        ; note $77 B8
    dw $07F0                        ; note $78 C9
    dw $07F1                        ; note $79 C#9
    dw $07F2                        ; note $7A D9
    dw $07F3                        ; note $7B D#9
    dw $07F4                        ; note $7C E9

; Commands $A0-$B7
CommandTable:
    dw Cmd_End                      ; $A0
    dw Cmd_LoopOn                   ; $A1
    dw Cmd_LoopOff                  ; $A2
    dw Cmd_LoopStart                ; $A3
    dw Cmd_Slur                     ; $A4
    dw Cmd_DefaultLength            ; $A5
    dw Cmd_Volume                   ; $A6
    dw Cmd_Pan                      ; $A7
    dw Cmd_Envelope                 ; $A8
    dw Cmd_LoopEnd                  ; $A9
    dw Cmd_Duty                     ; $AA
    dw Cmd_SeqTable                 ; $AB
    dw Cmd_Call                     ; $AC
    dw Cmd_SeqTable                 ; $AD
    dw Cmd_Wave                     ; $AE
    dw Cmd_Tempo                    ; $AF
    dw Cmd_Detune                   ; $B0
    dw Cmd_Transpose                ; $B1
    dw Cmd_Gate                     ; $B2
    dw Cmd_Jump                     ; $B3
    dw Cmd_Marker                   ; $B4
    dw Cmd_Return                   ; $B5
    dw Cmd_MasterVolume             ; $B6
    dw Cmd_Vibrato                  ; $B7

; Sound_Update: call once per frame.
; Music tracks tick once every (tempo+1) frames; the SFX track every 2nd frame.
Sound_Update::
    ld de,hSndTempoCount            ; $421B tempo divider
    ld a,[de]                       ; $421E
    ld hl,hSndTempo                 ; $421F
    cp [hl]                         ; $4222
    jr z,.tick                      ; $4223
    inc a                           ; $4225
    ld [de],a                       ; $4226
    jr .sfx                         ; $4227
.tick
    xor a                           ; $4229 tick: reset divider
    ld [de],a                       ; $422A
    ldh [hSndChannel],a             ; $422B
    ldh [hSndStructOfs],a           ; $422D
    ldh a,[hSndFlags]               ; $422F b = channel-on bits
    ld b,a                          ; $4231
.channelLoop
    rr b                            ; $4232 next channel bit
    jr nc,.nextChannel              ; $4234
    push bc                         ; $4236
    ld l,TRK_FLAGS                  ; $4237
    call Snd_GetVar                 ; $4239
    and $01                         ; $423C muted = SFX owns this channel
    ldh [hSndMuted],a               ; $423E
    call Snd_TickTrack              ; $4240
    pop bc                          ; $4243
.nextChannel
    ldh a,[hSndStructOfs]           ; $4244
    add a,$30                       ; $4246 next struct
    ldh [hSndStructOfs],a           ; $4248
    ldh a,[hSndChannel]             ; $424A
    inc a                           ; $424C
    ldh [hSndChannel],a             ; $424D
    cp $04                          ; $424F
    jr c,.channelLoop               ; $4251
.sfx
    ldh a,[hSndFlags]               ; $4253
    bit 4,a                         ; $4255 SFX playing?
    ret z                           ; $4257
    ld hl,hSndSfxFrame              ; $4258 SFX runs every 2nd frame
    inc [hl]                        ; $425B
    ld a,[hl]                       ; $425C
    rra                             ; $425D
    ret c                           ; $425E
    ldh a,[hSndSfxChannel]          ; $425F SFX: channel = its target channel
    ldh [hSndChannel],a             ; $4261
    xor a                           ; $4263
    ldh [hSndMuted],a               ; $4264
    ld a,$C0                        ; $4266 struct 4
    ldh [hSndStructOfs],a           ; $4268

; Snd_TickTrack: one tick of the track at hSndStructOfs on hardware
; channel hSndChannel. hSndMuted = channel in use by the SFX (no register writes).
Snd_TickTrack:
    xor a                           ; $426A
    ldh [hSndRetrigger],a           ; $426B
    ld l,TRK_LENGTH                 ; $426D
    call Snd_GetVar                 ; $426F
    dec [hl]                        ; $4272 length done -> new row
    jr z,.newRow                    ; $4273
    ld l,TRK_GATECOUNT              ; $4275 gate counter
    call Snd_GetVarH                ; $4277
    or a                            ; $427A
    ret z                           ; $427B already released: nothing to do
    dec [hl]                        ; $427C
    jp z,Snd_NoteOff                ; $427D gate reached -> note off
    ld l,TRK_FLAGS                  ; $4280
    call Snd_GetVar                 ; $4282
    bit 7,[hl]                      ; $4285 SFX just ended here: wait for a new row
    ret nz                          ; $4287
    ldh a,[hSndChannel]             ; $4288
    cp $02                          ; $428A
    call nz,Snd_EnvTick             ; $428C envelope (not ch3)
    ldh a,[hSndChannel]             ; $428F
    cp $03                          ; $4291
    call z,Snd_SeqTick              ; $4293 noise list (ch4)
    ldh a,[hSndChannel]             ; $4296
    cp $02                          ; $4298
    call c,Snd_VibratoTick          ; $429A vibrato (ch1/ch2)
    jr .output                      ; $429D
.newRow
    ld l,TRK_FLAGS                  ; $429F
    call Snd_GetVarH                ; $42A1
    res 7,[hl]                      ; $42A4
    xor a                           ; $42A6 clear the slur flag for this row
    ldh [hSndSlur],a                ; $42A7
    ld l,TRK_PTR                    ; $42A9
    call Snd_GetVarWord             ; $42AB
    ld e,c                          ; $42AE
    ld d,b                          ; $42AF
.readByte
    ld a,[de]                       ; $42B0
    inc de                          ; $42B1
    cp $80                          ; $42B2 $80-$FF: command
    jr nc,.command                  ; $42B4
    push af                         ; $42B6
    ld b,a                          ; $42B7
    ld l,TRK_NOTE                   ; $42B8 a = old note
    call Snd_GetVar                 ; $42BA
    ld [hl],b                       ; $42BD TRK_NOTE = new note
    ld l,TRK_PREVNOTE               ; $42BE
    call Snd_SetVar                 ; $42C0 TRK_PREVNOTE = old note
    pop af                          ; $42C3
    call Snd_PlayNote               ; $42C4
    jr .saveRow                     ; $42C7
.command
    call Snd_DoCommand              ; $42C9
    ldh a,[hSndStructOfs]           ; $42CC
    cp $C0                          ; $42CE SFX struct?
    jr nz,.music                    ; $42D0
    ldh a,[hSndFlags]               ; $42D2
    bit 4,a                         ; $42D4 SFX still running: keep parsing
    jr z,.saveRow                   ; $42D6
    jr .readByte                    ; $42D8
.music
    call Snd_IsChannelOn            ; $42DA music: keep parsing while the channel is on
    jr nz,.readByte                 ; $42DD
.saveRow
    ld c,e                          ; $42DF
    ld b,d                          ; $42E0
    ld l,TRK_PTR                    ; $42E1
    call Snd_SetVarWord             ; $42E3
.output
    ldh a,[hSndRetrigger]           ; $42E6 retrigger requested?
    or a                            ; $42E8
    ret z                           ; $42E9
    ldh a,[hSndMuted]               ; $42EA
    or a                            ; $42EC not while the SFX owns the channel
    ret nz                          ; $42ED
    ld h,a                          ; $42EE
    ldh a,[hSndChannel]             ; $42EF
    cp $03                          ; $42F1
    jr z,.trigger                   ; $42F3
    cp $02                          ; $42F5
    jr nz,.notWave                  ; $42F7
    ld l,TRK_VOLUME                 ; $42F9
    call Snd_GetVar                 ; $42FB
    ldh [rNR32],a                   ; $42FE NR32 = output level
    ld a,$80                        ; $4300
    ldh [rNR30],a                   ; $4302 wave DAC on
.notWave
    ld l,TRK_FREQ+1                 ; $4304
    call Snd_GetVar                 ; $4306 period high bits
    ld h,a                          ; $4309
.trigger
    call Snd_GetChannelRegs         ; $430A
    ld c,e                          ; $430D
    inc c                           ; $430E
    ld a,$80                        ; $430F
    or h                            ; $4311
    ldh [c],a                       ; $4312 NRx4 = trigger | period high
    ret                             ; $4313

; Snd_NoteOff: silence the channel (NRx2 = 8, retrigger; ch3: NR30 = 0).
Snd_NoteOff:
    ldh a,[hSndMuted]               ; $4314
    or a                            ; $4316
    ret nz                          ; $4317
    ldh a,[hSndChannel]             ; $4318
    cp $02                          ; $431A
    jr nz,Snd_WaveOff.notWave       ; $431C
Snd_WaveOff:
    xor a                           ; $431E
    ldh [rNR32],a                   ; $431F ch3: NR32 = 0, NR30 = 0
    ldh [rNR30],a                   ; $4321
    ret                             ; $4323
.notWave
    push de                         ; $4324
    call Snd_GetChannelRegs         ; $4325
    ld c,e                          ; $4328
    dec c                           ; $4329
    ld a,$08                        ; $432A
    ldh [c],a                       ; $432C NRx2 = 8 (volume 0, up)
    inc c                           ; $432D
    inc c                           ; $432E
    ld a,$80                        ; $432F
    ldh [c],a                       ; $4331 NRx4 = trigger
    pop de                          ; $4332
    ret                             ; $4333

; Snd_KeyOn: request the trigger write and write the period (or start the drum).
Snd_KeyOn:
    ldh a,[hSndMuted]               ; $4334
    or a                            ; $4336
    ret nz                          ; $4337
    inc a                           ; $4338
    ldh [hSndRetrigger],a           ; $4339 request the trigger write
Snd_WriteFreq:
    push de                         ; $433B
    call Snd_GetChannelRegs         ; $433C
    ldh a,[rNR52]                   ; $433F
    or d                            ; $4341
    ldh [rNR52],a                   ; $4342 NR52 |= channel bit (read-only bits, no effect)
    ldh a,[hSndChannel]             ; $4344
    cp $03                          ; $4346
    jr nz,.notNoise                 ; $4348
    call Snd_DrumInit               ; $434A ch4: start the drum
    jr .done                        ; $434D
.notNoise
    ld l,TRK_FREQ                   ; $434F
    call Snd_GetVarWord             ; $4351
    ld a,c                          ; $4354
    ld c,e                          ; $4355
    ldh [c],a                       ; $4356 NRx3
    inc c                           ; $4357
    ld a,b                          ; $4358
    ldh [c],a                       ; $4359 NRx4 (no trigger yet)
.done
    pop de                          ; $435A
    ret                             ; $435B

; Snd_GetChannelRegs: d = NR52-style channel bit | $80, e = LOW(NRx3).
Snd_GetChannelRegs:
    ldh a,[hSndChannel]             ; $435C
    ld d,$81                        ; $435E
    ld e,$13                        ; $4360
    or a                            ; $4362
    ret z                           ; $4363
    ld d,$82                        ; $4364
    ld e,$18                        ; $4366
    dec a                           ; $4368
    ret z                           ; $4369
    ld d,$84                        ; $436A
    ld e,$1D                        ; $436C
    dec a                           ; $436E
    ret z                           ; $436F
    ld d,$88                        ; $4370
    ld e,$22                        ; $4372
    ret                             ; $4374

; Snd_PlayNote: a = note byte (rest, or note). Handles the slur, key-on and
; the optional length byte that follows the note.
Snd_PlayNote:
    cp $7F                          ; $4375 rest is $7F here
    jr nz,.note                     ; $4377
    ld l,TRK_FLAGS                  ; $4379
    call Snd_GetVar                 ; $437B
    res 1,[hl]                      ; $437E rest clears the slur
    call Snd_NoteOff                ; $4380
    jr .length                      ; $4383
.note
    call Snd_CalcFreq               ; $4385
    ld l,TRK_FLAGS                  ; $4388
    call Snd_GetVar                 ; $438A
    ldh a,[hSndSlur]                ; $438D slur ($A4) on this row?
    or a                            ; $438F
    jr z,.noSlur                    ; $4390
    bit 1,[hl]                      ; $4392
    jr nz,.compare                  ; $4394
    set 1,[hl]                      ; $4396 first slurred note: key on, remember
    jr .keyOn                       ; $4398
.noSlur
    bit 1,[hl]                      ; $439A
    jr z,.keyOn                     ; $439C
    res 1,[hl]                      ; $439E last note of a slur
.compare
    ld l,TRK_NOTE                   ; $43A0
    call Snd_GetVarH                ; $43A2
    ld b,a                          ; $43A5
    ld l,TRK_PREVNOTE               ; $43A6
    call Snd_GetVarH                ; $43A8
    cp b                            ; $43AB same pitch as the previous note: tie, no key-on
    jr z,.length                    ; $43AC
.keyOn
    call Snd_NoteOff                ; $43AE release, then key on
    call Snd_KeyOn                  ; $43B1
    push de                         ; $43B4
    ldh a,[hSndChannel]             ; $43B5
    cp $00                          ; $43B7
    call z,Snd_SweepInit            ; $43B9 ch1: sweep
    ldh a,[hSndChannel]             ; $43BC
    cp $02                          ; $43BE
    call nz,Snd_VolumeInit          ; $43C0 not ch3: volume/duty/envelope
    ldh a,[hSndChannel]             ; $43C3
    cp $02                          ; $43C5
    call c,Snd_VibratoInit          ; $43C7 ch1/ch2: vibrato
    pop de                          ; $43CA
.length
    ld a,[de]                       ; $43CB
    cp $80                          ; $43CC length byte follows?
    jr c,.defaultLength             ; $43CE
    cp $A0                          ; $43D0
    jr nc,.defaultLength            ; $43D2
    call Snd_GetLength              ; $43D4 ticks from LengthTable
    inc de                          ; $43D7
    jr .setLength                   ; $43D8
.defaultLength
    ld l,TRK_DEFLEN                 ; $43DA
    call Snd_GetVar                 ; $43DC no: default length
.setLength
    ld b,a                          ; $43DF
    ld l,TRK_LENGTH                 ; $43E0
    call Snd_SetVar                 ; $43E2 TRK_LENGTH
    ld l,TRK_GATE                   ; $43E5
    call Snd_GetVarH                ; $43E7
    or a                            ; $43EA gate 0 = full length
    jr z,.setGate                   ; $43EB
    ld c,a                          ; $43ED
    srl b                           ; $43EE b = length / 8 (at least 1)
    srl b                           ; $43F0
    srl b                           ; $43F2
    jr nz,.multiply                 ; $43F4
    ld b,$01                        ; $43F6
.multiply
    xor a                           ; $43F8
.mulLoop
    add a,b                         ; $43F9 b * gate
    dec c                           ; $43FA
    jr nz,.mulLoop                  ; $43FB
    ld b,a                          ; $43FD
.setGate
    ld a,b                          ; $43FE
    ld l,TRK_GATECOUNT              ; $43FF
    jp Snd_SetVar                   ; $4401 TRK_GATECOUNT

; Snd_CalcFreq: TRK_FREQ = FreqTable[note - $24 + transpose] + detune.
; Notes below $24 give period 0 (used for noise "notes").
Snd_CalcFreq:
    ld l,TRK_NOTE                   ; $4404
    call Snd_GetVar                 ; $4406
    ld bc,$0000                     ; $4409
    cp $24                          ; $440C below $24: period 0
    jr c,.store                     ; $440E
    sub $24                         ; $4410
    inc hl                          ; $4412
    add a,[hl]                      ; $4413 + transpose
    push hl                         ; $4414
    ld l,a                          ; $4415
    ld h,b                          ; $4416
    add hl,hl                       ; $4417
    ld bc,FreqTable                 ; $4418 FreqTable
    add hl,bc                       ; $441B
    ld a,[hl+]                      ; $441C
    ld h,[hl]                       ; $441D
    ld l,a                          ; $441E
    pop bc                          ; $441F
    inc bc                          ; $4420
    ld a,[bc]                       ; $4421 + detune (signed)
    ld c,a                          ; $4422
    ld b,$00                        ; $4423
    bit 7,a                         ; $4425
    jr z,.positive                  ; $4427
    dec b                           ; $4429
.positive
    add hl,bc                       ; $442A
    ld c,l                          ; $442B
    ld b,h                          ; $442C
.store
    ld l,TRK_FREQ                   ; $442D
    jp Snd_SetVarWord               ; $442F

; Snd_VibratoTick: ch1/ch2 only. Modes: 1 triangle (one-sided), 2 slide down,
; 3 slide up. Changes TRK_DETUNE and rewrites the period without retrigger.
Snd_VibratoTick:
    ld l,TRK_VIBMODE                ; $4432
    call Snd_GetVar                 ; $4434
    ld b,a                          ; $4437 vibrato off
    or a                            ; $4438
    ret z                           ; $4439
    ld l,TRK_VIBDELAY               ; $443A
    call Snd_GetVar                 ; $443C
    or a                            ; $443F
    jr z,.step                      ; $4440 still in the delay
    dec [hl]                        ; $4442
    ret                             ; $4443
.step
    ld l,TRK_VIBRATE                ; $4444
    call Snd_GetVar                 ; $4446
    dec [hl]                        ; $4449 rate countdown
    ret nz                          ; $444A
    ld l,TRK_VIBRATER               ; $444B
    call Snd_GetVar                 ; $444D
    ld l,TRK_VIBRATE                ; $4450
    call Snd_SetVar                 ; $4452
    ld l,TRK_VIBSTEP                ; $4455 c = step
    call Snd_GetVar                 ; $4457
    ld c,a                          ; $445A
    ld l,TRK_DETUNE                 ; $445B
    call Snd_GetVar                 ; $445D
    dec b                           ; $4460 mode 1
    jr z,.triangle                  ; $4461
    dec b                           ; $4463 mode 2
    jr z,.slideDown                 ; $4464
    add a,c                         ; $4466 mode 3: up
    ld [hl],a                       ; $4467
    jr .update                      ; $4468
.slideDown
    sub c                           ; $446A mode 2: down
    ld [hl],a                       ; $446B
    jr .update                      ; $446C
.triangle
    ld l,TRK_VIBHALF                ; $446E
    call Snd_GetVar                 ; $4470
    dec [hl]                        ; $4473 half period done:
    jr nz,.apply                    ; $4474
    ld l,TRK_VIBHALFR               ; $4476
    call Snd_GetVar                 ; $4478
    ld l,TRK_VIBHALF                ; $447B
    call Snd_SetVar                 ; $447D
    ld a,c                          ; $4480
    cpl                             ; $4481 negate the step
    inc a                           ; $4482
    ld c,a                          ; $4483
    ld l,TRK_VIBSTEP                ; $4484
    call Snd_SetVar                 ; $4486
.apply
    ld l,TRK_DETUNE                 ; $4489
    call Snd_GetVar                 ; $448B
    add a,c                         ; $448E
    ld [hl],a                       ; $448F
.update
    ldh a,[hSndMuted]               ; $4490
    or a                            ; $4492
    ret nz                          ; $4493 not while muted
    call Snd_CalcFreq               ; $4494
    ldh a,[hSndChannel]             ; $4497
    cp $02                          ; $4499
    jp z,Snd_KeyOn                  ; $449B (only ch1/ch2 get here, so always the second jump)
    jp Snd_WriteFreq                ; $449E

; Snd_VibratoInit: reload all vibrato counters at key-on; detune = 0.
Snd_VibratoInit:
    ld l,TRK_VIBMODE                ; $44A1
    call Snd_GetVar                 ; $44A3
    or a                            ; $44A6
    ret z                           ; $44A7
    ld l,TRK_VIBDEPTH               ; $44A8
    call Snd_GetVar                 ; $44AA step = depth
    ld l,TRK_VIBSTEP                ; $44AD
    call Snd_SetVar                 ; $44AF
    ld l,TRK_VIBDELAYR              ; $44B2
    call Snd_GetVar                 ; $44B4 delay
    ld l,TRK_VIBDELAY               ; $44B7
    call Snd_SetVar                 ; $44B9
    ld l,TRK_VIBRATER               ; $44BC
    call Snd_GetVar                 ; $44BE rate
    ld l,TRK_VIBRATE                ; $44C1
    call Snd_SetVar                 ; $44C3
    ld l,TRK_VIBHALFR               ; $44C6
    call Snd_GetVar                 ; $44C8 half period
    ld l,TRK_VIBHALF                ; $44CB
    call Snd_SetVar                 ; $44CD
    xor a                           ; $44D0
    ld l,TRK_DETUNE                 ; $44D1
    jp Snd_SetVar                   ; $44D3 detune = 0

; Snd_VolumeInit: key-on for ch1/2/4: NRx2 volume nibble, NRx1 duty, and
; start the $A8 envelope list if one is set.
Snd_VolumeInit:
    ldh a,[hSndMuted]               ; $44D6
    or a                            ; $44D8
    ret nz                          ; $44D9
    call Snd_GetChannelRegs         ; $44DA
    ld l,TRK_VOLUME                 ; $44DD
    call Snd_GetVar                 ; $44DF
    swap a                          ; $44E2 volume nibble -> NRx2 bits 4-7
    ld b,a                          ; $44E4
    ld c,e                          ; $44E5
    dec c                           ; $44E6
    ldh a,[c]                       ; $44E7
    and $0F                         ; $44E8
    or b                            ; $44EA
    ldh [c],a                       ; $44EB
    ld a,[hl+]                      ; $44EC
    ld a,[hl]                       ; $44ED
    ld c,e                          ; $44EE
    dec c                           ; $44EF
    dec c                           ; $44F0
    ldh [c],a                       ; $44F1 NRx1 = duty
    ld l,TRK_FLAGS                  ; $44F2
    call Snd_GetVarH                ; $44F4
    bit 2,a                         ; $44F7 envelope list set?
    ret z                           ; $44F9
    set 5,[hl]                      ; $44FA start it
Snd_EnvStart:
    ld l,TRK_ENVBASE                ; $44FC
    call Snd_GetVarWord             ; $44FE
    ld l,TRK_ENVPTR                 ; $4501
    call Snd_SetVarWord             ; $4503 TRK_ENVPTR = TRK_ENVBASE

; Snd_EnvNextStep: read the next (NRx2 value, ticks) pair of the envelope list.
Snd_EnvNextStep:
    ld l,TRK_ENVPTR                 ; $4506
    call Snd_GetVarWord             ; $4508
    ld a,[bc]                       ; $450B
    ld e,a                          ; $450C
    inc bc                          ; $450D
    ld a,[bc]                       ; $450E
    ld d,a                          ; $450F
    inc bc                          ; $4510
    ld a,b                          ; $4511
    ld [hl-],a                      ; $4512
    ld [hl],c                       ; $4513
    ld a,e                          ; $4514
    ld l,TRK_ENVVALUE               ; $4515 value
    call Snd_SetVar                 ; $4517
    ld a,d                          ; $451A
    ld l,TRK_ENVCOUNT               ; $451B ticks
    call Snd_SetVar                 ; $451D
    cp $FE                          ; $4520 $FE/$FF: no write
    ret nc                          ; $4522
    ldh a,[hSndMuted]               ; $4523
    or a                            ; $4525
    ret nz                          ; $4526
    ld c,$12                        ; $4527
    ldh a,[hSndChannel]             ; $4529
    cp $00                          ; $452B
    jr z,.write                     ; $452D
    ld c,$17                        ; $452F
    cp $01                          ; $4531
    jr z,.write                     ; $4533
    ld c,$21                        ; $4535
.write
    ld a,e                          ; $4537 NRx2 = value
    ldh [c],a                       ; $4538
    ret                             ; $4539

; Snd_EnvTick: count down the current envelope step; at 0 take the next pair
; and retrigger. Duration $FE = restart the list, $FF = stop.
Snd_EnvTick:
    ld l,TRK_FLAGS                  ; $453A
    call Snd_GetVar                 ; $453C
    bit 5,a                         ; $453F
    ret z                           ; $4541
    ld l,TRK_ENVCOUNT               ; $4542
    call Snd_GetVar                 ; $4544
    dec [hl]                        ; $4547
    ret nz                          ; $4548
    call Snd_EnvNextStep            ; $4549
    ld a,d                          ; $454C
    cp $FE                          ; $454D $FE: restart
    jp z,Snd_EnvStart               ; $454F
    cp $FF                          ; $4552 $FF: stop
    jr nz,.retrigger                ; $4554
    ld l,TRK_FLAGS                  ; $4556
    call Snd_GetVar                 ; $4558
    res 5,[hl]                      ; $455B
    ret                             ; $455D
.retrigger
    ldh a,[hSndMuted]               ; $455E
    or a                            ; $4560
    ret nz                          ; $4561
    inc a                           ; $4562
    ldh [hSndRetrigger],a           ; $4563 retrigger to apply the new NRx2
    ret                             ; $4565

; Snd_SweepInit (ch1): NR10 = first value of the $AB/$AD list.
Snd_SweepInit:
    ld l,TRK_SEQTABLE               ; $4566
    call Snd_GetVarWord             ; $4568
    jr Snd_DrumInit.startSeq        ; $456B

; Snd_DrumInit (ch4): kit entry (note - $0A) & 7 = [noise list, envelope list].
Snd_DrumInit:
    ld l,TRK_SEQTABLE               ; $456D
    call Snd_GetVarWord             ; $456F
    ld l,TRK_NOTE                   ; $4572
    call Snd_GetVar                 ; $4574
    sub $0A                         ; $4577 drum = (note - $0A) & 7
    and $07                         ; $4579
    add a,a                         ; $457B
    add a,a                         ; $457C
    ld l,a                          ; $457D
    ld h,$00                        ; $457E
    add hl,bc                       ; $4580
    ld a,[hl+]                      ; $4581
    ld c,a                          ; $4582
    ld a,[hl+]                      ; $4583
    ld b,a                          ; $4584
    push bc                         ; $4585
    ld a,[hl+]                      ; $4586
    ld c,a                          ; $4587
    ld b,[hl]                       ; $4588
    call Snd_SetEnvelope            ; $4589 second word: envelope list
    pop bc                          ; $458C
.startSeq
    ld l,TRK_SEQPTR                 ; $458D
    call Snd_SetVarWord             ; $458F first word: noise list
    ld l,TRK_FLAGS                  ; $4592
    call Snd_GetVar                 ; $4594
    bit 3,a                         ; $4597 table set?
    ret z                           ; $4599
    set 4,[hl]                      ; $459A

; Snd_SeqNextStep: read the next (value, ticks) pair; NR10 (ch1) or NR43 (ch4).
Snd_SeqNextStep:
    ld l,TRK_SEQPTR                 ; $459C
    call Snd_GetVarWord             ; $459E
    ld a,[bc]                       ; $45A1
    ld e,a                          ; $45A2
    inc bc                          ; $45A3
    ld a,[bc]                       ; $45A4
    ld d,a                          ; $45A5
    inc bc                          ; $45A6
    ld a,b                          ; $45A7
    ld [hl-],a                      ; $45A8
    ld [hl],c                       ; $45A9
    ld a,e                          ; $45AA
    ld l,TRK_SEQVALUE               ; $45AB
    call Snd_SetVar                 ; $45AD value
    ld a,d                          ; $45B0
    ld l,TRK_SEQCOUNT               ; $45B1
    call Snd_SetVar                 ; $45B3 ticks
    ld a,d                          ; $45B6
    cp $FE                          ; $45B7 $FE/$FF: no write
    ret nc                          ; $45B9
    ldh a,[hSndMuted]               ; $45BA
    or a                            ; $45BC
    ret nz                          ; $45BD
    ld c,$22                        ; $45BE
    ldh a,[hSndChannel]             ; $45C0
    cp $03                          ; $45C2
    jr z,.write                     ; $45C4
    ld c,$10                        ; $45C6
.write
    ld a,e                          ; $45C8
    ldh [c],a                       ; $45C9 NR10 (ch1) or NR43 (ch4)
    ret                             ; $45CA

; Snd_SeqTick (ch4 only): step the noise list. $FE = restart the drum, $FF = stop.
Snd_SeqTick:
    ld l,TRK_FLAGS                  ; $45CB
    call Snd_GetVar                 ; $45CD
    bit 4,a                         ; $45D0
    ret z                           ; $45D2
    ld l,TRK_SEQCOUNT               ; $45D3
    call Snd_GetVar                 ; $45D5
    dec [hl]                        ; $45D8
    ret nz                          ; $45D9
    call Snd_SeqNextStep            ; $45DA
    ld a,d                          ; $45DD
    cp $FE                          ; $45DE
    jp z,Snd_DrumInit               ; $45E0 $FE: restart the drum
    cp $FF                          ; $45E3 $FF: stop
    jr nz,.retrigger                ; $45E5
    ld l,TRK_FLAGS                  ; $45E7
    call Snd_GetVar                 ; $45E9
    res 4,[hl]                      ; $45EC
    ret                             ; $45EE
.retrigger
    ldh a,[hSndMuted]               ; $45EF
    or a                            ; $45F1
    ret nz                          ; $45F2
    inc a                           ; $45F3
    ldh [hSndRetrigger],a           ; $45F4
    ret                             ; $45F6

; Snd_DoCommand: a = command byte $A0-$B7, de = argument pointer.
Snd_DoCommand:
    sub $A0                         ; $45F7
    jr c,Snd_GetLength.invalid      ; $45F9 below $A0 ...
    cp $B8                          ; $45FB
    jr nc,Snd_GetLength.invalid     ; $45FD ... or above $B7: ignored (1 byte)
    add a,a                         ; $45FF
    ld c,a                          ; $4600
    ld b,$00                        ; $4601
    ld hl,CommandTable              ; $4603
    add hl,bc                       ; $4606
    ld a,[hl+]                      ; $4607
    ld h,[hl]                       ; $4608
    ld l,a                          ; $4609
    jp hl                           ; $460A
Cmd_DefaultLength:
    ld a,[de]                       ; $460B
    inc de                          ; $460C
    call Snd_GetLength              ; $460D
    ld l,TRK_DEFLEN                 ; $4610
    jp Snd_SetVar                   ; $4612

; Snd_GetLength: a = length code $80-$9F -> ticks from LengthTable.
Snd_GetLength:
    sub $80                         ; $4615
    ld hl,LengthTable               ; $4617
    ld c,a                          ; $461A
    ld b,$00                        ; $461B
    add hl,bc                       ; $461D
    ld a,[hl]                       ; $461E
    ret                             ; $461F
.invalid
    ret                             ; $4620 invalid command byte: ignored

; Cmd_End ($A0). SFX track: stop the SFX and give the channel back to the music.
; Music track: loop to TRK_START, or stop the channel if $A2 (no-loop) is set.
Cmd_End:
    ldh a,[hSndStructOfs]           ; $4621
    cp $C0                          ; $4623 SFX struct?
    jr nz,.music                    ; $4625
    call Snd_NoteOff                ; $4627 SFX end: release the channel
    push hl                         ; $462A
    ld hl,hSndFlags                 ; $462B SFX off
    res 4,[hl]                      ; $462E
    pop hl                          ; $4630
    xor a                           ; $4631
    ldh [hSndSfxPriority],a         ; $4632 SFX priority = 0
    ldh a,[hSndSfxChannel]          ; $4634
    or a                            ; $4636
    jr nz,.notCh1                   ; $4637
    ld a,$08                        ; $4639
    ldh [rNR14],a                   ; $463B ch1: NR14 = $08 first
    ld c,$12                        ; $463D
    jr .silence                     ; $463F
.notCh1
    ld c,$17                        ; $4641
    dec a                           ; $4643
    jr z,.silence                   ; $4644
    dec a                           ; $4646
    jr z,.release                   ; $4647
    ld c,$21                        ; $4649
.silence
    ld a,$08                        ; $464B
    ldh [c],a                       ; $464D NRx2 = 8
    inc c                           ; $464E
    inc c                           ; $464F
    ld a,$80                        ; $4650
    ldh [c],a                       ; $4652 NRx4 = trigger
.release
    ldh a,[hSndSfxChannel]          ; $4653
    call Snd_GetStructAddr          ; $4655 music struct of that channel
    ld c,l                          ; $4658
    ld a,$0E                        ; $4659
    add a,l                         ; $465B
    ld l,a                          ; $465C
    res 0,[hl]                      ; $465D not SFX-owned any more
    set 7,[hl]                      ; $465F pause its effects until the next row
    ld a,c                          ; $4661 bug: meant to read TRK_PAN (no ld l,a), so a = TRK_FLAGS (>= $80) and
    add a,$13                       ; $4662
    ld a,[hl]                       ; $4664 the channel always gets centre pan
    jp Snd_SetPan                   ; $4665
.music
    ldh a,[hSndFlags]               ; $4668
    bit 7,a                         ; $466A no-loop mode?
    jr z,.loop                      ; $466C
    call Snd_NoteOff                ; $466E
    jp Snd_StopChannel              ; $4671
.loop
    ld l,TRK_START                  ; $4674
    call Snd_GetVarWord             ; $4676 de = TRK_START
    ld e,c                          ; $4679
    ld d,b                          ; $467A
    inc hl                          ; $467B TRK_PTR = TRK_START
    ld [hl],c                       ; $467C
    inc hl                          ; $467D
    ld [hl],b                       ; $467E
    ld a,[de]                       ; $467F
    cp $A0                          ; $4680 empty track: stop
    ret nz                          ; $4682
    jp Snd_StopChannel              ; $4683

; Snd_StopChannel: clear the channel bit in hSndFlags.
Snd_StopChannel:
    ldh a,[hSndChannel]             ; $4686
    ld b,$FE                        ; $4688
    or a                            ; $468A
    jr z,.clear                     ; $468B
    ld b,$FD                        ; $468D
    dec a                           ; $468F
    jr z,.clear                     ; $4690
    ld b,$FB                        ; $4692
    dec a                           ; $4694
    jr z,.clear                     ; $4695
    ld b,$F7                        ; $4697
.clear
    ldh a,[hSndFlags]               ; $4699
    and b                           ; $469B
    ldh [hSndFlags],a               ; $469C
    ret                             ; $469E

; Snd_IsChannelOn: nz if this music channel is still running.
Snd_IsChannelOn:
    ldh a,[hSndChannel]             ; $469F
    ld b,$01                        ; $46A1
    or a                            ; $46A3
    jr z,.test                      ; $46A4
    ld b,$02                        ; $46A6
    dec a                           ; $46A8
    jr z,.test                      ; $46A9
    ld b,$04                        ; $46AB
    dec a                           ; $46AD
    jr z,.test                      ; $46AE
    ld b,$08                        ; $46B0
.test
    ldh a,[hSndFlags]               ; $46B2
    and b                           ; $46B4
    ret                             ; $46B5
Cmd_Volume:
    ld a,[de]                       ; $46B6
    inc de                          ; $46B7
    ld c,a                          ; $46B8
    ldh a,[hSndChannel]             ; $46B9
    cp $02                          ; $46BB
    jr nz,.store                    ; $46BD ch3: NR32 value from WaveVolTable
    ld hl,WaveVolTable              ; $46BF
    ld b,$00                        ; $46C2
    add hl,bc                       ; $46C4
    ld c,[hl]                       ; $46C5
.store
    ld a,c                          ; $46C6
    ld l,TRK_VOLUME                 ; $46C7
    jp Snd_SetVar                   ; $46C9
Cmd_MasterVolume:
    ld a,[de]                       ; $46CC
    inc de                          ; $46CD
    ldh [hSndMasterVol],a           ; $46CE
    ldh [rNR50],a                   ; $46D0 NR50
    ret                             ; $46D2
Cmd_Slur:
    ld a,$01                        ; $46D3
    ldh [hSndSlur],a                ; $46D5
    ret                             ; $46D7
Cmd_LoopOn:
    ld hl,hSndFlags                 ; $46D8
    res 7,[hl]                      ; $46DB
    ret                             ; $46DD
Cmd_LoopOff:
    ld hl,hSndFlags                 ; $46DE
    set 7,[hl]                      ; $46E1
    ret                             ; $46E3
Cmd_Tempo:
    ld a,[de]                       ; $46E4
    inc de                          ; $46E5
    ld b,a                          ; $46E6
    ldh a,[hSndStructOfs]           ; $46E7
    cp $C0                          ; $46E9 not from the SFX
    ret z                           ; $46EB
    ld a,b                          ; $46EC
    ldh [hSndTempo],a               ; $46ED tempo (and tick on the next frame)
    ldh [hSndTempoCount],a          ; $46EF
    ret                             ; $46F1
Cmd_Marker:
    ld a,[de]                       ; $46F2
    inc de                          ; $46F3
    ldh [hSndMarker],a              ; $46F4
    ret                             ; $46F6
Cmd_Duty:
    ld a,[de]                       ; $46F7
    inc de                          ; $46F8
    ld b,a                          ; $46F9
    ldh a,[hSndChannel]             ; $46FA
    cp $02                          ; $46FC ch1/ch2 only
    ret nc                          ; $46FE
    ld a,b                          ; $46FF
    swap a                          ; $4700 arg * $40
    add a,a                         ; $4702
    add a,a                         ; $4703
    ld l,TRK_DUTY                   ; $4704
    jp Snd_SetVar                   ; $4706
Cmd_SeqTable:
    ld a,[de]                       ; $4709
    ld c,a                          ; $470A
    inc de                          ; $470B
    ld a,[de]                       ; $470C
    inc de                          ; $470D
    ld b,a                          ; $470E
    ld l,TRK_SEQTABLE               ; $470F
    call Snd_SetVarWord             ; $4711
    ld l,TRK_FLAGS                  ; $4714
    call Snd_GetVarH                ; $4716
    set 3,[hl]                      ; $4719
    ret                             ; $471B
Cmd_Envelope:
    ld a,[de]                       ; $471C
    inc de                          ; $471D
    ld c,a                          ; $471E
    ld a,[de]                       ; $471F
    inc de                          ; $4720
    ld b,a                          ; $4721
Snd_SetEnvelope:
    ld l,TRK_ENVBASE                ; $4722
    call Snd_SetVarWord             ; $4724
    ld l,TRK_FLAGS                  ; $4727
    call Snd_GetVarH                ; $4729
    set 2,[hl]                      ; $472C
    ret                             ; $472E
Cmd_Wave:
    ld a,[de]                       ; $472F first argument byte is not used
    inc de                          ; $4730
    call Snd_ReadPtrPtr             ; $4731
    ldh a,[hSndMuted]               ; $4734
    or a                            ; $4736 not while muted
    ret nz                          ; $4737
    ldh [rNR30],a                   ; $4738 NR30 = 0
    ld c,$30                        ; $473A
    ld b,$10                        ; $473C
.copy
    ld a,[hl+]                      ; $473E
    ldh [c],a                       ; $473F wave RAM
    inc c                           ; $4740
    dec b                           ; $4741
    jr nz,.copy                     ; $4742
    ld a,$80                        ; $4744
    ldh [rNR30],a                   ; $4746 NR30 = $80
    ldh [hSndRetrigger],a           ; $4748 retrigger
    ret                             ; $474A
Snd_ReadPtrPtr:
    ld a,[de]                       ; $474B
    inc de                          ; $474C
    ld l,a                          ; $474D
    ld a,[de]                       ; $474E
    inc de                          ; $474F
    ld h,a                          ; $4750
    ld a,[hl+]                      ; $4751 hl = word at the pointer
    ld h,[hl]                       ; $4752
    ld l,a                          ; $4753
    ret                             ; $4754
Cmd_Pan:
    ld a,[de]                       ; $4755
    inc de                          ; $4756
    ld l,TRK_PAN                    ; $4757
    call Snd_SetVar                 ; $4759
    ld l,TRK_PAN                    ; $475C
    call Snd_GetVar                 ; $475E
    and $03                         ; $4761 1 = right, 2 = left, else both
Snd_SetPan:
    ld b,$01                        ; $4763
    ld c,$EE                        ; $4765
    dec a                           ; $4767
    jr z,.shift                     ; $4768
    ld b,$10                        ; $476A
    ld c,$EE                        ; $476C
    dec a                           ; $476E
    jr z,.shift                     ; $476F
    ld b,$11                        ; $4771
    ld c,$EE                        ; $4773
.shift
    ldh a,[hSndChannel]             ; $4775
    or a                            ; $4777
    jr z,.write                     ; $4778
.shiftLoop
    rlc b                           ; $477A shift to this channel
    rlc c                           ; $477C
    dec a                           ; $477E
    jr nz,.shiftLoop                ; $477F
.write
    ldh a,[hSndMuted]               ; $4781
    or a                            ; $4783
    ret nz                          ; $4784
    ldh a,[rNR51]                   ; $4785 NR51
    and c                           ; $4787
    or b                            ; $4788
    ldh [rNR51],a                   ; $4789
    ret                             ; $478B
Cmd_Call:
    ld a,[de]                       ; $478C
    inc de                          ; $478D
    ld l,TRK_CALLCOUNT              ; $478E
    call Snd_SetVar                 ; $4790 repeat count
    ld c,e                          ; $4793
    ld b,d                          ; $4794
    ld l,TRK_CALLRET                ; $4795
    call Snd_SetVarWord             ; $4797 TRK_CALLRET = address of the pointer
    ld l,e                          ; $479A
    ld h,d                          ; $479B
    ld e,[hl]                       ; $479C jump to the subroutine
    inc hl                          ; $479D
    ld d,[hl]                       ; $479E
    ret                             ; $479F
Cmd_Return:
    ld l,TRK_CALLCOUNT              ; $47A0
    call Snd_GetVar                 ; $47A2
    dec [hl]                        ; $47A5 last pass?
    jr nz,.again                    ; $47A6
    ld l,TRK_CALLRET                ; $47A8
    call Snd_GetVarWordH            ; $47AA
    inc bc                          ; $47AD continue after the $AC pointer
    inc bc                          ; $47AE
    jr .jump                        ; $47AF
.again
    ld l,TRK_CALLRET                ; $47B1
    call Snd_GetVarWordH            ; $47B3
    ld l,c                          ; $47B6
    ld h,b                          ; $47B7
    ld c,[hl]                       ; $47B8 run the subroutine again
    inc hl                          ; $47B9
    ld b,[hl]                       ; $47BA
.jump
    ld e,c                          ; $47BB
    ld d,b                          ; $47BC
    ret                             ; $47BD
Cmd_Jump:
    ld l,e                          ; $47BE
    ld h,d                          ; $47BF
    ld e,[hl]                       ; $47C0 de = target
    inc hl                          ; $47C1
    ld d,[hl]                       ; $47C2
    ret                             ; $47C3
Cmd_Detune:
    ld a,[de]                       ; $47C4
    inc de                          ; $47C5
    ld l,TRK_DETUNE                 ; $47C6
    jp Snd_SetVar                   ; $47C8
Cmd_Transpose:
    ld a,[de]                       ; $47CB
    inc de                          ; $47CC
    ld l,TRK_TRANSPOSE              ; $47CD
    jp Snd_SetVar                   ; $47CF
Cmd_Gate:
    ld a,[de]                       ; $47D2
    and $07                         ; $47D3 0-7
    inc de                          ; $47D5
    ld l,TRK_GATE                   ; $47D6
    jp Snd_SetVar                   ; $47D8
Cmd_LoopStart:
    xor a                           ; $47DB
    ld l,TRK_LOOPCOUNT              ; $47DC
    call Snd_SetVar                 ; $47DE pass = 0
    ld c,e                          ; $47E1
    ld b,d                          ; $47E2
    ld l,TRK_LOOPPTR                ; $47E3
    jp Snd_SetVarWord               ; $47E5 TRK_LOOPPTR = here
Cmd_LoopEnd:
    ld a,[de]                       ; $47E8
    inc de                          ; $47E9
    ld b,a                          ; $47EA
    ld l,TRK_LOOPCOUNT              ; $47EB
    call Snd_GetVar                 ; $47ED
    inc [hl]                        ; $47F0 pass + 1
    ld a,[hl]                       ; $47F1
    cp b                            ; $47F2
    ret nc                          ; $47F3 last pass: continue
    ld l,TRK_LOOPPTR                ; $47F4
    call Snd_GetVarWordH            ; $47F6
    ld e,c                          ; $47F9 back to the loop start
    ld d,b                          ; $47FA
    ret                             ; $47FB
Cmd_Vibrato:
    ld a,[de]                       ; $47FC
    and $3F                         ; $47FD bits 0-5: depth
    ld l,TRK_VIBDEPTH               ; $47FF
    call Snd_SetVar                 ; $4801
    ld a,[de]                       ; $4804
    inc de                          ; $4805
    swap a                          ; $4806
    rra                             ; $4808
    rra                             ; $4809
    and $03                         ; $480A bits 6-7: mode
    ld l,TRK_VIBMODE                ; $480C
    call Snd_SetVar                 ; $480E
    ld a,[de]                       ; $4811
    inc de                          ; $4812
    ld l,TRK_VIBDELAYR              ; $4813
    call Snd_SetVar                 ; $4815 delay
    ld a,[de]                       ; $4818
    inc de                          ; $4819
    ld l,TRK_VIBRATER               ; $481A
    call Snd_SetVar                 ; $481C rate
    ld a,[de]                       ; $481F
    inc de                          ; $4820
    ld l,TRK_VIBHALFR               ; $4821
    call Snd_SetVar                 ; $4823 half period
    xor a                           ; $4826
    ld l,TRK_DETUNE                 ; $4827
    jp Snd_SetVar                   ; $4829 detune = 0

; Track struct accessors: l = offset (TRK_*), result in a / bc.
Snd_GetVar:
    ld h,HIGH(wSndTracks)           ; $482C
Snd_GetVarH:
    ldh a,[hSndStructOfs]           ; $482E
    add a,l                         ; $4830
    ld l,a                          ; $4831
    ld a,[hl]                       ; $4832
    ret                             ; $4833
Snd_GetVarWord:
    ld h,HIGH(wSndTracks)           ; $4834
Snd_GetVarWordH:
    ldh a,[hSndStructOfs]           ; $4836
    add a,l                         ; $4838
    ld l,a                          ; $4839
    ld a,[hl+]                      ; $483A
    ld c,a                          ; $483B
    ld b,[hl]                       ; $483C
    ret                             ; $483D

; Track struct accessors: l = offset, h is set to the struct page here.
Snd_SetVar:
    ld h,a                          ; $483E
    ldh a,[hSndStructOfs]           ; $483F
    add a,l                         ; $4841
    ld l,a                          ; $4842
    ld a,h                          ; $4843
    ld h,HIGH(wSndTracks)           ; $4844
    ld [hl],a                       ; $4846
    ret                             ; $4847
Snd_SetVarWord:
    ld h,HIGH(wSndTracks)           ; $4848
    ldh a,[hSndStructOfs]           ; $484A
    add a,l                         ; $484C
    ld l,a                          ; $484D
    ld a,c                          ; $484E
    ld [hl+],a                      ; $484F
    ld [hl],b                       ; $4850
    ret                             ; $4851

; Snd_StartSfx: hl -> pointer to the SFX header.
Snd_StartSfx:
    ldh a,[rIE]                     ; $4852 IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $4854
    res 1,a                         ; $4855
    ldh [rIE],a                     ; $4857
    ld a,[hl+]                      ; $4859
    ld h,[hl]                       ; $485A
    ld l,a                          ; $485B
    ld b,[hl]                       ; $485C
    inc hl                          ; $485D
    ldh a,[hSndSfxPriority]         ; $485E
    ld c,a                          ; $4860
    ld a,[hl]                       ; $4861
    cp c                            ; $4862 lower priority than the current SFX: ignore
    jr c,.done                      ; $4863
    ldh a,[hSndFlags]               ; $4865
    bit 4,a                         ; $4867 SFX already playing?
    jr z,.start                     ; $4869
    call Snd_EndSfx                 ; $486B end it first
.start
    ld a,[hl+]                      ; $486E
    ldh [hSndSfxPriority],a         ; $486F priority
    ld a,b                          ; $4871
    ldh [hSndSfxChannel],a          ; $4872 target channel
    push hl                         ; $4874
    call Snd_GetStructAddr          ; $4875
    ld a,$0E                        ; $4878
    add a,l                         ; $487A
    ld l,a                          ; $487B
    set 0,[hl]                      ; $487C mark the music track as SFX-owned
    pop de                          ; $487E
    ld a,$04                        ; $487F
    call Snd_InitTrack              ; $4881 struct 4 = the SFX
    ld hl,hSndFlags                 ; $4884
    set 4,[hl]                      ; $4887 SFX on
.done
    pop af                          ; $4889
    ldh [rIE],a                     ; $488A
    ret                             ; $488C

; Snd_EndSfx: end the playing SFX (Cmd_End on struct 4). Also called by
; Sound_StopMusic, so stopping the music stops the SFX too.
Snd_EndSfx:
    push bc                         ; $488D
    push hl                         ; $488E
    ldh a,[hSndChannel]             ; $488F
    push af                         ; $4891
    ldh a,[hSndStructOfs]           ; $4892
    push af                         ; $4894
    ldh a,[hSndSfxChannel]          ; $4895
    ldh [hSndChannel],a             ; $4897
    ld a,$C0                        ; $4899
    ldh [hSndStructOfs],a           ; $489B
    xor a                           ; $489D
    ldh [hSndMuted],a               ; $489E
    call Cmd_End                    ; $48A0 end it first
    pop af                          ; $48A3
    ldh [hSndStructOfs],a           ; $48A4
    pop af                          ; $48A6
    ldh [hSndChannel],a             ; $48A7
    pop hl                          ; $48A9
    pop bc                          ; $48AA
    ret                             ; $48AB

; Sound_Init: power the APU on, set all registers from InitRegs, clear the
; flags of all 5 structs, then fall into Sound_StopMusic.
Sound_Init::
    ld c,$26                        ; $48AC
    xor a                           ; $48AE
    ldh [c],a                       ; $48AF APU off
    ld a,$8F                        ; $48B0
    ldh [c],a                       ; $48B2 APU on
    dec c                           ; $48B3
    ld a,$FF                        ; $48B4
    ldh [c],a                       ; $48B6 NR51 = $FF
    dec c                           ; $48B7
    ld a,$77                        ; $48B8
    ldh [c],a                       ; $48BA NR50 = $77
    ld hl,InitRegs                  ; $48BB
    ld c,$10                        ; $48BE
.regLoop
    ld a,[hl+]                      ; $48C0
    ldh [c],a                       ; $48C1 NR10-NR23 from InitRegs
    inc c                           ; $48C2
    ld a,c                          ; $48C3
    cp $24                          ; $48C4
    jr c,.regLoop                   ; $48C6
    xor a                           ; $48C8
    ldh [hSndFlags],a               ; $48C9
    ldh [hSndMarker],a              ; $48CB
    ldh [hSndSfxChannel],a          ; $48CD
    ldh [hSndSfxPriority],a         ; $48CF
.flagLoop
    push af                         ; $48D1
    call Snd_GetStructAddr          ; $48D2
    ld a,$0E                        ; $48D5
    add a,l                         ; $48D7
    ld l,a                          ; $48D8
    ld [hl],$00                     ; $48D9 flags = 0
    pop af                          ; $48DB
    inc a                           ; $48DC
    cp $05                          ; $48DD
    jr nz,.flagLoop                 ; $48DF
Sound_StopMusic::
    call Snd_EndSfx                 ; $48E1 stop the SFX as well (falls through from Sound_Init too)

; Sound_StopMusic: start the silent song.
    ld hl,SilentSong                ; $48E4

; Snd_StartMusic: hl -> 4 track pointers. Tempo 4, all 4 channels on.
Snd_StartMusic:
    ldh a,[rIE]                     ; $48E7 IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $48E9
    res 1,a                         ; $48EA
    ldh [rIE],a                     ; $48EC
    ldh a,[hSndFlags]               ; $48EE
    and $F0                         ; $48F0
    ldh [hSndFlags],a               ; $48F2 channels off
    ld a,$04                        ; $48F4
    ldh [hSndTempoCount],a          ; $48F6
    ldh [hSndTempo],a               ; $48F8 tempo 4, tick at once
    xor a                           ; $48FA
.trackLoop
    ld e,[hl]                       ; $48FB
    inc hl                          ; $48FC
    ld d,[hl]                       ; $48FD
    inc hl                          ; $48FE
    push af                         ; $48FF
    push hl                         ; $4900
    call Snd_InitTrack              ; $4901
    pop hl                          ; $4904
    pop af                          ; $4905
    inc a                           ; $4906
    cp $04                          ; $4907
    jr c,.trackLoop                 ; $4909
    ld a,$01                        ; $490B
    ld [$00A8],a                    ; $490D writes to ROM ($0000-$1FFF = MBC RAM-enable); looks like a typo for RAM vars
    ld [$00A9],a                    ; $4910
    ld a,$80                        ; $4913
    ldh [rNR30],a                   ; $4915
    call Snd_WaveOff                ; $4917 NR32 = 0, NR30 = 0
    ldh a,[hSndFlags]               ; $491A
    or $0F                          ; $491C
    ldh [hSndFlags],a               ; $491E channels 1-4 on
    pop af                          ; $4920
    ldh [rIE],a                     ; $4921 restore IE
    ret                             ; $4923

; Snd_InitTrack: a = struct index, de = data. Clears the struct (keeps
; TRKF_SFXOWNED), TRK_START = TRK_PTR = de, default length 1, volume $C.
Snd_InitTrack:
    call Snd_GetStructAddr          ; $4924
    ld a,$0E                        ; $4927
    add a,l                         ; $4929
    ld c,a                          ; $492A
    ld b,h                          ; $492B
    ld a,[bc]                       ; $492C
    and $01                         ; $492D
    push af                         ; $492F keep TRKF_SFXOWNED
    push bc                         ; $4930
    push hl                         ; $4931
    xor a                           ; $4932
    ld b,$30                        ; $4933
.clear
    ld [hl+],a                      ; $4935
    dec b                           ; $4936
    jr nz,.clear                    ; $4937
    pop hl                          ; $4939
    pop bc                          ; $493A
    pop af                          ; $493B
    ld [bc],a                       ; $493C
    ld a,l                          ; $493D
    ld [hl],e                       ; $493E
    inc hl                          ; $493F TRK_START
    ld [hl],d                       ; $4940
    inc hl                          ; $4941
    ld [hl],e                       ; $4942
    inc hl                          ; $4943 TRK_PTR
    ld [hl],d                       ; $4944
    add a,$0F                       ; $4945
    ld l,a                          ; $4947
    ld a,$01                        ; $4948
    ld [hl+],a                      ; $494A TRK_DEFLEN = 1, TRK_LENGTH = 1
    ld [hl+],a                      ; $494B
    ld [hl],$0C                     ; $494C TRK_VOLUME = $C
    ret                             ; $494E

; Snd_GetStructAddr: hl = struct a (a * $30).
Snd_GetStructAddr:
    push af                         ; $494F
    ld h,a                          ; $4950
    inc h                           ; $4951
    ld a,$00                        ; $4952
.mulLoop
    dec h                           ; $4954
    jr z,.done                      ; $4955
    add a,$30                       ; $4957
    jr .mulLoop                     ; $4959
.done
    ld l,a                          ; $495B
    ld h,HIGH(wSndTracks)           ; $495C
    pop af                          ; $495E
    ret                             ; $495F

